/**
 * Fetches MAPID's commercial property listings and stores them as a single point
 * file, ready to be joined onto the hexagon grid.
 *
 *   node scripts/fetch-property.mjs
 *   node scripts/fetch-property.mjs --report-only   # rewrite the doc from the file on disk
 *
 * Output:
 *   src/lib/data/mapid-property.json  — points + a coverage declaration
 *   docs/mapid-property.md            — the list of datasets read
 *
 * WHAT THIS IS FOR
 *
 * The third signal in the opportunity score is whether there is space to be had. Up
 * to now that came from `listing`, a SAMPLE column generated by `build-hexes.mjs`,
 * because the Properti Go mission dataset is not public. This reads the real thing:
 * the premium catalogue publishes commercial units on the market, city by city, with
 * an asking price attached.
 *
 * THE CATALOGUE SELLS, IT DOES NOT LET
 *
 * This was checked before any of it was written, because the whole point was rent.
 * Every property dataset the catalogue holds for DKI Jakarta was read and its TIPE_3
 * column tallied: 83 datasets, 30,629 rows, and the tally comes back
 *
 *   JUAL 19,018 · APARTEMEN SEKEN 5,449 · RUMAH SEKEN 2,457 · RUKO SEKEN 1,416 ·
 *   TANAH RESIDENSIAL 1,213 · TANAH KOMERSIAL 931 · RUMAH BARU 111 · APARTEMEN BARU 34
 *
 * with no SEWA among them, in any city, in any family. TIPE_3 is exactly the
 * sale-or-rent dimension — `fetch-missions.mjs` reads the same distinction out of
 * Properti Go's `Jenis Properti` — so this is not an absence of the column, it is an
 * absence of rent in it.
 *
 * 176 rows do contain the word SEWA. All of them in ALAMAT, in listing prose of the
 * form "DI JUAL SEWA APARTEMEN KEMANG MANSION FULL FURNISHED". That is an advert, not
 * a rent, and matching on it would have produced a rent figure out of a sale price.
 *
 * So what is stored here is an ASKING PRICE FOR SALE, and it is named that way
 * everywhere it travels: `price`, not `rent`. A monthly rent could be produced from it
 * with a yield assumption, and that assumption would be the one number on the screen
 * that came from nobody's data. Rebuild this file and re-run the tally if MAPID ever
 * publishes SEWA rows — the manifest below picks them up with no change, because it
 * selects datasets, not TIPE_3 values.
 *
 * PRICE PER M² IS THE CATALOGUE'S OWN COLUMN, NOT A DIVISION DONE HERE
 *
 * `HARGA PER M2` is published on 187 of 399 Jakarta Pusat ruko rows, and on every one
 * of those it equals `HARGA (Rp)` ÷ `LUAS TANAH (M2)` to within a rounding step. It is
 * therefore a price per m² OF LAND, and it is taken verbatim.
 *
 * Recomputing it against `LUAS BANGUNAN` — floor area, which is what a tenant actually
 * occupies and the more useful denominator — is deliberately NOT done. That column is
 * absent or zero on 283 of those 399 rows, so a fallback would silently mix two
 * different measures in one median, and the half that came out four times higher would
 * be indistinguishable from the half that did not.
 */

import { writeFileSync, mkdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { cleanName, mapidKey, matchesDataset, normCity, projectId, readLayer, searchPremium } from './lib/mapid.mjs';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');

/** The five DKI administrative cities. The catalogue ships one dataset per city. */
const CITIES = ['JAKARTA PUSAT', 'JAKARTA BARAT', 'JAKARTA SELATAN', 'JAKARTA TIMUR', 'JAKARTA UTARA'];

/**
 * The commercial property families, and whether a small business could take the unit.
 *
 * `unit: true` means premises somebody could open a coffee shop or a laundry in. That
 * is the set the price level and the space gate are computed from, and it is a
 * narrower set than "commercial": an office floor and a warehouse are both commercial
 * property, both are on the market, and neither is a shopfront. Their prices per m²
 * belong to a different market, so folding them into one median would produce a figure
 * for a kind of space nobody is looking for.
 *
 * They are fetched anyway, tagged with their type, because "what else is on the market
 * around here" is worth showing next to a cell even when it is not what the score is
 * about.
 *
 * The residential families — APARTEMEN, RUMAH, KOST, KONTRAKAN, VILLA — are not
 * fetched at all. 13,500 flats and 5,600 houses would swamp 2,500 shophouses in every
 * count on screen, and none of them is a place to open a business.
 */
const MANIFEST = [
	{ term: 'PROPERTI RUKO', type: 'ruko', unit: true },
	{ term: 'PROPERTI TOKO KIOS', type: 'toko', unit: true },
	{ term: 'PROPERTI RUANG USAHA', type: 'ruang', unit: true },
	{ term: 'PROPERTI RUKAN', type: 'rukan', unit: true },
	{ term: 'PROPERTI KOMERSIAL LAINNYA', type: 'komersial', unit: true },
	{ term: 'PROPERTI KANTOR', type: 'kantor', unit: false },
	{ term: 'PROPERTI GEDUNG', type: 'gedung', unit: false },
	{ term: 'PROPERTI GUDANG', type: 'gudang', unit: false }
];

/**
 * The naming pattern of the catalogue's official publications, e.g.
 * "PROPERTI RUKO DI KOTA ADMINISTRASI JAKARTA PUSAT TAHUN 2025".
 *
 * Used to break a tie when a search matches more than one dataset, so the choice is
 * made by a rule rather than by search ranking, which can shift at any time and swap a
 * complete dataset for a smaller one without anyone noticing.
 */
const CANONICAL = /\bDI\s+KOTA\b.*\bTAHUN\s+\d{4}/i;

/** A positive number out of whatever the column holds, or null. Never zero: the
    catalogue writes an unknown area and an unknown price alike as "0" or "", and a
    zero that reached a median would drag it towards a value nobody measured. */
function positive(v) {
	if (typeof v === 'number') return Number.isFinite(v) && v > 0 ? v : null;
	const s = String(v ?? '').replace(/[^0-9.]/g, '');
	if (!s) return null;
	const n = Number(s);
	return Number.isFinite(n) && n > 0 ? n : null;
}

/** A small integer out of a column that holds one, or null. */
function count(v) {
	const n = positive(v);
	return n === null ? null : Math.round(n);
}

/** Rewrites `docs/mapid-property.md` from the point file already on disk, no network. */
function reportOnly() {
	const src = resolve(ROOT, 'src/lib/data/mapid-property.json');
	const data = JSON.parse(readFileSync(src, 'utf8'));
	writeFileSync(resolve(ROOT, 'docs/mapid-property.md'), report(data.meta));
	console.log(`Rebuilt docs/mapid-property.md from ${src}`);
	console.log(`${data.meta.layers.length} layers · ${data.meta.total} listings · no network used`);
}

async function main() {
	if (process.argv.includes('--report-only')) return reportOnly();

	const key = mapidKey();
	console.log(`Project ${projectId()} (used as the read ticket)\n`);

	// ── 1. Find the datasets in the premium catalogue ──────────────────────
	console.log('[1/2] Searching the premium catalogue…');
	const wanted = [];
	const missing = [];

	for (const { term, type, unit } of MANIFEST) {
		for (const city of CITIES) {
			const hits = await searchPremium(`${term} ${city}`);
			const matched = hits.filter((l) => matchesDataset(l.name, term, city));
			const hit = matched.find((l) => CANONICAL.test(l.name ?? '')) ?? matched[0];
			if (hit) wanted.push({ id: hit._id, name: hit.name, term, city, type, unit });
			else missing.push({ term, city });
		}
		const got = wanted.filter((w) => w.term === term).length;
		console.log(`      ${term.padEnd(26)} ${got}/${CITIES.length} cities`);
	}

	// ── 2. Read the contents ───────────────────────────────────────────────
	console.log(`\n[2/2] Fetching the contents of ${wanted.length} layers…`);
	const points = [];
	const perLayer = [];
	/** Cities whose datasets were read, per unit type — the same declared-coverage rule
	    `fetch-mapid.mjs` follows: a dataset read successfully covers its city however
	    many rows survive. A city absent from here was NOT CHECKED, which is not the
	    same fact as a city with nothing on the market. */
	const coverage = new Set();
	/** TIPE_3 tallied across everything read, so the "no rent in the catalogue" finding
	    at the top of this file is re-measured on every run rather than being quoted
	    from the day it was true. */
	const tipe3 = {};

	for (const [i, w] of wanted.entries()) {
		const { features } = await readLayer(w.id, key, w.name);
		let kept = 0;
		let priced = 0;

		for (const f of features) {
			const p = f.properties ?? {};
			const t3 = String(p.TIPE_3 ?? '?').trim() || '?';
			tipe3[t3] = (tipe3[t3] ?? 0) + 1;

			const c = f.geometry?.coordinates;
			const lat = Array.isArray(c) && c.length >= 2 ? c[1] : positive(p.LATITUDE) === null ? null : Number(p.LATITUDE);
			const lon = Array.isArray(c) && c.length >= 2 ? c[0] : Number(p.LONGITUDE);
			if (!Number.isFinite(lat) || !Number.isFinite(lon)) continue;

			// Taken verbatim from the catalogue's own column, never divided here — see the
			// note at the top of this file.
			const ppm = positive(p['HARGA PER M2']);
			if (ppm !== null) priced++;

			points.push({
				lat: Math.round(lat * 1e5) / 1e5,
				lon: Math.round(lon * 1e5) / 1e5,
				type: w.type,
				unit: w.unit,
				/** Asking price for SALE in rupiah. The catalogue has no rent. */
				price: positive(p['HARGA (Rp)']),
				/** Asking price per m² of LAND, as published. */
				ppm,
				land: positive(p['LUAS TANAH (M2)']),
				build: positive(p['LUAS BANGUNAN (M2)']),
				floors: count(p['JUMLAH LANTAI']),
				cert: cleanName(p['STATUS SERTIFIKAT']),
				name: cleanName(p.NAMA),
				addr: cleanName(p.ALAMAT),
				city: p.KABKOT ?? null,
				// The sale-or-rent value, carried through rather than assumed. It reads
				// JUAL on every row today; storing it is what lets the join and the
				// interface keep saying so from the data.
				sale: t3
			});
			kept++;
		}

		coverage.add(normCity(w.city));
		perLayer.push({ id: w.id, name: w.name, term: w.term, city: w.city, type: w.type, unit: w.unit, features: features.length, kept, priced });
		console.log(
			`  [${String(i + 1).padStart(2)}/${wanted.length}] ${String(features.length).padStart(5)} rows → ` +
				`${String(kept).padStart(5)} kept · ${String(priced).padStart(5)} priced · ${w.name.slice(0, 52)}`
		);
	}

	const byType = points.reduce((a, p) => ((a[p.type] = (a[p.type] ?? 0) + 1), a), {});
	const priced = points.filter((p) => p.ppm !== null);
	const unitPriced = priced.filter((p) => p.unit);

	const out = {
		meta: {
			source: 'MAPID premium data (Data Premium) via geoserver.mapid.io',
			project_id: projectId(),
			read: 'Straight from the premium catalogue — a catalogue layer_id + our own project_id. No manual import step.',
			listingType:
				'ASKING PRICES FOR SALE. The catalogue publishes no rent listings for DKI Jakarta: every TIPE_3 value read is a sale category, and `tipe3` below is that tally, re-measured on this run.',
			tipe3,
			layers: perLayer,
			missing,
			total: points.length,
			byType,
			pricedTotal: priced.length,
			unitTotal: points.filter((p) => p.unit).length,
			unitPricedTotal: unitPriced.length,
			priceColumn:
				'`HARGA PER M2` verbatim from the catalogue, which publishes it as asking price ÷ LUAS TANAH. Not recomputed against floor area, which is absent on most rows.',
			coverage: [...coverage].sort(),
			coverageRule:
				'Written from the datasets that were read successfully, not inferred from the listings that survived. A city not listed means NOT CHECKED — not "nothing on the market".',
			regenerate: 'node scripts/fetch-property.mjs'
		},
		points
	};

	const dest = resolve(ROOT, 'src/lib/data/mapid-property.json');
	mkdirSync(dirname(dest), { recursive: true });
	writeFileSync(dest, JSON.stringify(out));
	writeFileSync(resolve(ROOT, 'docs/mapid-property.md'), report(out.meta));

	console.log(`\n${points.length} listings · ${priced.length} carry a price per m²`);
	console.log('by type:', byType);
	console.log('TIPE_3 :', tipe3);
	console.log(`coverage: ${[...coverage].sort().join(', ')}`);
	console.log(`\n→ ${dest}`);
	console.log('→ docs/mapid-property.md');
}

/** Markdown report: what was read, and what the tally says about rent. */
function report(meta) {
	const fmt = (n) => Number(n).toLocaleString('en-US');
	const L = [
		'<!-- Generated by `node scripts/fetch-property.mjs` — do not edit by hand. -->',
		'',
		'# The MAPID property datasets SpotOn reads',
		'',
		`${meta.layers.length} premium catalogue datasets · ${fmt(meta.total)} listings, ` +
			`${fmt(meta.pricedTotal)} of them with a price per m².`,
		'',
		'## Is there rent data in the catalogue?',
		'',
		'**No.** Every property dataset published for DKI Jakarta was read and its `TIPE_3`',
		'column tallied. `TIPE_3` is the sale-or-rent dimension. What comes back is:',
		'',
		'| TIPE_3 | Rows |',
		'|---|--:|'
	];
	for (const [k, v] of Object.entries(meta.tipe3).sort((a, b) => b[1] - a[1])) {
		L.push(`| ${k} | ${fmt(v)} |`);
	}
	L.push('');
	L.push('Every one of them is a sale category. So what this file holds, and what the map');
	L.push('shows, is an **asking price for sale**. It is never called a rent, and a rent is');
	L.push('never derived from it: that would take a yield assumption, and the assumption');
	L.push('would be the only figure on screen that came from nobody\'s data.');
	L.push('');
	L.push('The tally is recomputed on every run rather than written down once, so the day');
	L.push('MAPID publishes a SEWA row it shows up here on its own.');
	L.push('');
	L.push('## What was read', '');
	L.push('| Type | Premises | City | Dataset | Rows | Kept | Priced |');
	L.push('|---|---|---|---|--:|--:|--:|');
	for (const l of meta.layers) {
		L.push(
			`| ${l.type} | ${l.unit ? 'yes' : 'no'} | ${l.city} | \`${l.name}\` | ` +
				`${fmt(l.features)} | ${fmt(l.kept)} | ${fmt(l.priced)} |`
		);
	}
	L.push('');
	L.push('"Premises" marks the families a small business could actually occupy. The price');
	L.push('level and the space gate are computed from those alone: an office floor and a');
	L.push('warehouse are commercial property too, and neither is a shopfront, so their');
	L.push('prices per m² belong to a different market and would distort a median built for');
	L.push('someone looking for one.');
	L.push('');
	L.push(`Of ${fmt(meta.total)} listings, ${fmt(meta.unitTotal)} are premises and ` +
		`${fmt(meta.unitPricedTotal)} of those carry a price per m².`);
	L.push('');

	if (meta.missing?.length) {
		const byT = new Map();
		for (const m of meta.missing) {
			if (!byT.has(m.term)) byT.set(m.term, []);
			byT.get(m.term).push(m.city);
		}
		L.push('## Searched for, not found', '');
		for (const [term, cities] of byT) {
			L.push(`- **${term}** — ${cities.length === 5 ? 'all five cities' : cities.join(', ')}`);
		}
		L.push('');
		L.push('Left in the manifest so their absence keeps being tested rather than slowly');
		L.push('turning into an assumption, and so they are picked up if MAPID publishes them.');
		L.push('');
	}

	L.push('## Coverage', '');
	L.push(`Cities read: ${meta.coverage.join(', ') || '**none**'}.`);
	L.push('');
	L.push('Coverage is written from the datasets that were read, **not** inferred from the');
	L.push('listings that survived. A city absent from that list was never checked, and that');
	L.push('is not the same fact as a city with nothing on the market.');
	L.push('');

	return L.join('\n');
}

main().catch((err) => {
	console.error('Failed:', err.message);
	process.exit(1);
});
